207	    /**
208	     * The owner's age band, derived at response time from {@link #birthDate} against
209	     * {@link #registrationDate}: {@code MINOR} when under 18 years old, {@code ADULT} when 18 to 64,
210	     * and {@code SENIOR} when 65 or over. {@code null} when the owner has no birth date (or no
211	     * registration date to compute against). Not persisted.
212	     */
213	    public String getAgeBand() {
214	        if (this.birthDate == null || this.registrationDate == null) {
215	            return null;
216	        }
217	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
218	        if (age < 18) {
219	            return "MINOR";
220	        }
221	        if (age < 65) {
222	            return "ADULT";
223	        }
224	        return "SENIOR";
225	    }
