262	    /**
263	     * Whether this owner, when created, was a possible (soft) duplicate of an earlier owner: an
264	     * earlier non-deleted owner whose {@link #soundex(String) soundex(lastName)} and postcode both
265	     * matched this owner's, but whose {@link #getIdentityKey() identityKey} differed (so it was not a
266	     * hard duplicate — an exact identityKey match is rejected 409 and never reaches this flag).
267	     * {@code false} when no such earlier owner existed. Assigned at creation.
268	     */
269	    public Boolean getPossibleDuplicate() {
270	        return this.possibleDuplicate;
271	    }
272	
273	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
274	        this.possibleDuplicate = possibleDuplicate;
275	    }
