278	     * The id of the earlier owner this owner is a possible duplicate of (the earliest such match),
279	     * or {@code null} when {@link #getPossibleDuplicate()} is false. Assigned at creation.
280	     */
281	    public Integer getPossibleDuplicateOf() {
282	        return this.possibleDuplicateOf;
283	    }
284	
285	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
286	        this.possibleDuplicateOf = possibleDuplicateOf;
287	    }
