289	    /**
290	     * Whether this owner has been soft-deleted via {@code DELETE /api/owners/{id}}: the record is
291	     * retained and still returned by {@code GET /api/owners/{id}}, but is flagged {@code true} and
292	     * ignored by the create endpoint's duplicate and identity checks. {@code false} for a newly
293	     * created owner.
294	     */
295	    public Boolean getDeleted() {
296	        return this.deleted;
297	    }
298	
299	    public void setDeleted(Boolean deleted) {
300	        this.deleted = deleted;
