308	    /**
309	     * Whether more than 80 owners had already been created on this owner's registration day,
310	     * derived at response time and not persisted. {@code true} triggers a bulk-signup warning
311	     * in the response.
312	     */
313	    public Boolean getBulkSignupWarning() {
314	        return this.bulkSignupWarning;
315	    }
316	
317	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
318	        this.bulkSignupWarning = bulkSignupWarning;
319	    }
