321	    /**
322	     * Whether this owner's city already holds between 40 and 49 owners (inclusive), approaching the
323	     * hard capacity limit of 50. Derived at response time and not persisted; {@code true} triggers a
324	     * capacity warning in the response.
325	     */
326	    public Boolean getCapacityWarning() {
327	        return this.capacityWarning;
328	    }
329	
330	    public void setCapacityWarning(Boolean capacityWarning) {
331	        this.capacityWarning = capacityWarning;
332	    }
