334	    /**
335	     * The number of owners in this owner's household (owners sharing the same
336	     * {@link #householdId}), derived at response time and not persisted.
337	     */
338	    public Integer getHouseholdSize() {
339	        return this.householdSize;
340	    }
341	
342	    public void setHouseholdSize(Integer householdSize) {
343	        this.householdSize = householdSize;
344	    }
345	
346	    /**
347	     * The ceiling applied to {@link #getMembershipLevel() membershipLevel}: one above the current
348	     * maximum membershipLevel among this owner's existing household members. Derived at response
349	     * time and not persisted; {@code null} means no household member exists and no cap applies.
350	     */
351	    public Integer getMembershipLevelCap() {
352	        return this.membershipLevelCap;
353	    }
354	
355	    public void setMembershipLevelCap(Integer membershipLevelCap) {
356	        this.membershipLevelCap = membershipLevelCap;
357	    }
358	
359	    /**
360	     * Whether this owner is flagged as elevated risk, derived at response time and not persisted.
361	     * {@code true} when any of three soft signals holds: the owner is a {@link #getPossibleDuplicate()
362	     * possible duplicate}; the email domain is disposable-adjacent (see
363	     * {@code ValidateOwnerEmailDomain.isDisposableAdjacent}); or the owner's city is over its soft
364	     * capacity (see {@code DeriveOwnerRiskFlag.SOFT_CAPACITY}). {@code false} when none hold.
365	     * Populated by {@code DeriveOwnerRiskFlag} on both the create and single-owner GET responses.
366	     */
367	    public Boolean getRiskFlag() {
368	        return this.riskFlag;
369	    }
370	
371	    public void setRiskFlag(Boolean riskFlag) {
372	        this.riskFlag = riskFlag;
373	    }
374	
375	    /**
376	     * The owner's membership points, derived at response time. Starts at {@code 0}, plus 2 when an
377	     * email is present, plus 1 when {@link #namesakeCount} is 0, plus 2 when the
378	     * {@link #getHouseholdSize() household} has 3 or more members, plus 3 when tenure exceeds one
379	     * elapsed fiscal year (measured from the {@link #registrationDate}; see
380	     * {@link #getTenureFiscalYears()}).
381	     */
382	    public Integer getMembershipPoints() {
383	        int points = 0;
384	        if (this.email != null && !this.email.isEmpty()) {
385	            points += 2;
386	        }
387	        if (this.namesakeCount != null && this.namesakeCount == 0) {
388	            points += 1;
389	        }
390	        if (this.householdSize != null && this.householdSize >= 3) {
391	            points += 2;
392	        }
393	        if (getTenureFiscalYears() > 1) {
394	            points += 3;
395	        }
396	        return points;
397	    }
398	
399	    /**
400	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints() membershipPoints}:
401	     * {@code 1} for 0-1 points, {@code 2} for 2-3 points, {@code 3} for 4-5 points, and {@code 4} for
402	     * 6 or more points.
403	     *
404	     * <p>When a {@link #getMembershipLevelCap() membershipLevelCap} is present the result is capped to
405	     * it, so a new owner's level cannot exceed one above the current maximum membershipLevel among
406	     * their household members. With no household member the cap is absent and the mapped level stands.
407	     */
408	    public Integer getMembershipLevel() {
409	        int points = getMembershipPoints();
410	        int level;
411	        if (points <= 1) {
412	            level = 1;
413	        }
414	        else if (points <= 3) {
415	            level = 2;
416	        }
417	        else if (points <= 5) {
418	            level = 3;
419	        }
420	        else {
421	            level = 4;
422	        }
423	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
424	            return this.membershipLevelCap;
425	        }
426	        return level;
427	    }
428	
429	    /**
430	     * The fiscal year containing {@code date}: fiscal years start on 1 July and are named for the
431	     * calendar year in which they end, so 1 July 2026 – 30 June 2027 is fiscal year {@code 2027}.
432	     */
433	    public static int fiscalYear(LocalDate date) {
434	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
435	    }
436	
437	    /**
438	     * The owner's fiscal year, derived at response time from the (business-day-adjusted)
439	     * {@link #registrationDate} as {@code FY<YY>}, where the fiscal year starts on 1 July and
440	     * {@code YY} is the last two digits of the fiscal year (the calendar year in which it ends). This
441	     * is the same fiscal year the {@link #getMemberId() memberId} embeds, but it is computed directly
442	     * from the registration date rather than parsed out of the member id — so the version-2 tag mixed
443	     * into the member id never leaks into this value. {@code null} when the owner has no registration
444	     * date. Not persisted.
445	     */
446	    public String getFiscalYear() {
447	        if (this.registrationDate == null) {
448	            return null;
449	        }
450	        return "FY" + String.format(Locale.ROOT, "%02d", fiscalYear(this.registrationDate) % 100);
451	    }
452	
453	    /**
454	     * The owner's tenure in elapsed fiscal years, measured from the {@link #registrationDate}'s
455	     * fiscal year to the current fiscal year (fiscal years start on 1 July); zero when the
456	     * registration date is absent or falls in a later fiscal year than today.
457	     */
458	    private long getTenureFiscalYears() {
459	        if (this.registrationDate == null) {
460	            return 0;
461	        }
462	        long years = (long) fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate);
463	        return Math.max(years, 0);
464	    }
465	
466	    /**
467	     * The fixed identity-scheme version tag mixed into every version-2 identifier — the
468	     * {@link #getMemberId() memberId} (via its {@link #regionCodeV2(String) region code}), the
469	     * {@link #getHouseholdId() householdId} and the {@link #getIdentityKey() identityKey}. It appears
470	     * only inside those identifiers; the user-facing {@link #getLocality() locality},
471	     * {@link #getTimezone() timezone} and {@link #getOwnerSegment() owner segment} stay the plain
472	     * region code.
473	     */
474	    public static final String IDENTITY_VERSION = "V2";
475	
476	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
477	    private static final Map<String, String> CITY_REGION = Map.of(
478	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
479	
480	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive {@link #getLocality()}. */
481	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
482	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
483	
484	    /** Fixed region-to-IANA-timezone table used to derive {@link #getTimezone()}. */
485	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
486	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
487	
488	    /**
489	     * The fixed city-to-region mapping ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
490	     * {@code Brisbane -> QLD}): the region for {@code city}, or {@code null} when the city is not in
491	     * the table. Used only by postcode validation, which branches on "known region or not" by testing
492	     * for {@code null} before range-checking the postcode.
493	     */
494	    public static String regionOf(String city) {
495	        return CITY_REGION.get(city);
496	    }
497	
498	    /**
499	     * The region whose fixed postcode range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
500	     * {@code QLD 4000-4099}) contains {@code postcode}, or {@code null} when {@code postcode} is
501	     * absent, not a 4-digit number, or in no known range.
502	     */
503	    public static String regionOfPostcode(String postcode) {
504	        if (postcode == null || postcode.isEmpty()) {
505	            return null;
506	        }
507	        int value;
508	        try {
509	            value = Integer.parseInt(postcode);
510	        } catch (NumberFormatException ex) {
511	            return null;
512	        }
513	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
514	            int[] range = entry.getValue();
515	            if (value >= range[0] && value <= range[1]) {
516	                return entry.getKey();
517	            }
518	        }
519	        return null;
520	    }
521	
522	    /**
523	     * The version-2 region code embedded <em>inside</em> the identifiers: the plain region code with
524	     * the fixed {@link #IDENTITY_VERSION} tag appended (e.g. {@code NSWV2}, {@code UNKNOWNV2}). A
525	     * {@code null} region is treated as {@code UNKNOWN}. Because every version-1 identifier carried the
526	     * bare region code, mixing the tag in guarantees no version-2 identifier can ever reproduce a
527	     * version-1 value. This is an identifier-internal value only; the user-facing
528	     * {@link #getLocality() locality}, {@link #getTimezone() timezone} and {@link #getOwnerSegment()
529	     * owner segment} keep using the plain region code.
530	     */
531	    public static String regionCodeV2(String region) {
532	        return (region == null ? "UNKNOWN" : region) + IDENTITY_VERSION;
533	    }
534	
535	    /**
536	     * The owner's region, derived at response time directly from the {@link #getPostcode() postcode}
537	     * via {@link #regionOfPostcode(String)} — the plain region code ({@code NSW}, {@code VIC} or
538	     * {@code QLD}), or {@code UNKNOWN} when the postcode maps to no known region. This is the same
539	     * region the {@link #getMemberId() memberId} is built from, but it is the <em>plain</em> code:
540	     * the version-2 {@link #IDENTITY_VERSION} tag mixed into the member id never appears here.
541	     */
542	    public String getLocality() {
543	        String region = regionOfPostcode(this.postcode);
544	        return region == null ? "UNKNOWN" : region;
545	    }
546	
547	    /**
548	     * The owner's IANA timezone name, derived at response time from the {@link #getLocality()
549	     * locality}/region via the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
550	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null}
551	     * when the region is not in the table. Not persisted.
552	     */
553	    public String getTimezone() {
554	        return REGION_TIMEZONE.get(getLocality());
555	    }
556	
557	    /**
558	     * The owner's segment, derived at response time as {@code <TIER>_<AREA>} — one of
559	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
560	     * {@code STANDARD_REGIONAL}. TIER is {@code PREMIUM} when {@link #getMembershipLevel()
561	     * membershipLevel} is 3 or more, otherwise {@code STANDARD}. AREA is {@code METRO} when the
562	     * {@link #getLocality() locality} is a known region ({@code NSW}, {@code VIC} or {@code QLD}),
563	     * otherwise {@code REGIONAL}. Not persisted.
564	     */
565	    public String getOwnerSegment() {
566	        Integer level = getMembershipLevel();
567	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
568	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
569	        return tier + "_" + area;
570	    }
571	
572	    /**
573	     * The owner's preferred contact channel, derived at response time: {@code EMAIL} when an
574	     * email is present, otherwise {@code PHONE}. Not persisted.
575	     */
576	    public String getContactPreference() {
577	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
578	    }
579	
580	    /**
581	     * The owner's deterministic identity key: the full lower-case hex SHA-256 of
582	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. The telephone is
583	     * stored in canonical E.164 form and the email lower-cased; an absent telephone or email
584	     * contributes an empty segment, and the last name is reduced to its {@link #soundex(String)
585	     * Soundex} code. Two owners share an identity exactly when this 64-character hex value is equal.
586	     *
587	     * <p>This is the single key duplicate detection keys off: a create is rejected 409 when a
588	     * non-deleted owner already carries the same identity key (see {@code DetectOwnerDuplicate}).
589	     * Because the telephone participates in the key, two owners with the same last name and postcode
590	     * but different telephones no longer collide here — they are flagged as a soft match instead (see
591	     * {@code DetectOwnerPossibleDuplicate}). Derived at response time and not persisted.
592	     *
593	     * <p>The version-2 derivation mixes the fixed {@link #IDENTITY_VERSION} tag into the hashed input,
594	     * so every key differs from the version-1 value while owners that share an identity still share
595	     * the (new) key — the collision semantics are unchanged, only the value.
596	     */
597	    public String getIdentityKey() {
598	        String telephone = keyPart(this.telephone);
599	        String email = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
600	        String input = IDENTITY_VERSION + "|" + telephone + "|" + email + "|" + soundex(this.lastName);
601	        return sha256Hex(input);
602	    }
603	
604	    private static String keyPart(String value) {
605	        return value == null ? "" : value;
606	    }
607	
608	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
609	    private static String sha256Hex(String value) {
610	        try {
611	            byte[] digest = MessageDigest.getInstance("SHA-256")
612	                    .digest(value.getBytes(StandardCharsets.UTF_8));
613	            StringBuilder sb = new StringBuilder(digest.length * 2);
614	            for (byte b : digest) {
615	                sb.append(String.format("%02x", b));
616	            }
617	            return sb.toString();
618	        }
619	        catch (NoSuchAlgorithmException ex) {
620	            throw new IllegalStateException("SHA-256 not available", ex);
621	        }
622	    }
623	
624	    /**
625	     * The American Soundex code for {@code name}: the retained first letter followed by up to three
626	     * digits mapping the remaining consonants (b/f/p/v→1, c/g/j/k/q/s/x/z→2, d/t→3, l→4, m/n→5, r→6),
627	     * right-padded with zeros to length four. Adjacent duplicate codes collapse; {@code h}/{@code w}
628	     * do not separate repeated codes while vowels (and {@code y}) do. Non-letters are ignored. Returns
629	     * {@code ""} when {@code name} is null or has no letters. Two last names that sound alike share a
630	     * code, which is how the identity key and soft-match group surnames phonetically.
631	     */
632	    public static String soundex(String name) {
633	        if (name == null) {
634	            return "";
635	        }
636	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
637	        if (letters.isEmpty()) {
638	            return "";
639	        }
640	        StringBuilder code = new StringBuilder();
641	        code.append(letters.charAt(0));
642	        char prev = soundexDigit(letters.charAt(0));
643	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
644	            char c = letters.charAt(i);
645	            if (c == 'H' || c == 'W') {
646	                continue; // ignored and does not separate repeated codes
647	            }
648	            char digit = soundexDigit(c);
649	            if (digit != '0' && digit != prev) {
650	                code.append(digit);
651	            }
652	            prev = digit; // a vowel resets prev so a later same code is emitted again
653	        }
654	        while (code.length() < 4) {
655	            code.append('0');
656	        }
657	        return code.toString();
658	    }
659	
660	    /** The Soundex digit for an upper-case letter, {@code '0'} for vowels and {@code h}/{@code w}. */
661	    private static char soundexDigit(char c) {
662	        switch (c) {
663	            case 'B': case 'F': case 'P': case 'V':
664	                return '1';
665	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
666	                return '2';
667	            case 'D': case 'T':
668	                return '3';
669	            case 'L':
670	                return '4';
671	            case 'M': case 'N':
672	                return '5';
673	            case 'R':
674	                return '6';
675	            default:
676	                return '0';
677	        }
678	    }
679	
680	    /**
681	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
682	     * national digits (everything after the country code) grouped in threes and space-separated —
683	     * e.g. {@code +61412345678} becomes {@code +61 412 345 678}. The country code is recognised for
684	     * '+61' (2 digits) and '+1' (1 digit); any other prefix falls back to a 2-digit country code.
685	     * {@code null} when the telephone is absent or not a valid E.164 value. Derived at response time
686	     * and not persisted; the raw {@link #getTelephone() telephone} stays in E.164 form.
687	     */
688	    public String getTelephoneDisplay() {
689	        if (this.telephone == null || !this.telephone.matches("\\+\\d{8,15}")) {
690	            return null;
691	        }
692	        String digits = this.telephone.substring(1);
693	        int countryCodeLength;
694	        if (digits.startsWith("61")) {
695	            countryCodeLength = 2;
696	        }
697	        else if (digits.startsWith("1")) {
698	            countryCodeLength = 1;
699	        }
700	        else {
701	            countryCodeLength = 2;
702	        }
703	        String countryCode = digits.substring(0, countryCodeLength);
704	        String national = digits.substring(countryCodeLength);
705	        StringBuilder display = new StringBuilder("+").append(countryCode);
706	        for (int i = 0; i < national.length(); i += 3) {
707	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
708	        }
709	        return display.toString();
710	    }
711	
712	    protected Set<Pet> getPetsInternal() {
713	        if (this.pets == null) {
714	            this.pets = new HashSet<>();
715	        }
716	        return this.pets;
717	    }
718	
719	    protected void setPetsInternal(Set<Pet> pets) {
720	        this.pets = pets;
721	    }
722	
723	    public List<Pet> getPets() {
724	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
725	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
726	        return Collections.unmodifiableList(sortedPets);
727	    }
728	
729	    public void setPets(List<Pet> pets) {
730	        this.pets = new HashSet<>(pets);
731	    }
732	
733	    public void addPet(Pet pet) {
734	        getPetsInternal().add(pet);
735	        pet.setOwner(this);
736	    }
737	
738	    /**
739	     * Return the Pet with the given name, or null if none found for this Owner.
740	     *
741	     * @param name to test
742	     * @return true if pet name is already in use
743	     */
744	    public Pet getPet(String name) {
745	        return getPet(name, false);
746	    }
747	
748	    /**
749	     * Return the Pet with the given name, or null if none found for this Owner.
750	     *
751	     * @param name to test
752	     * @return true if pet name is already in use
753	     */
754	    public Pet getPet(String name, boolean ignoreNew) {
755	        name = name.toLowerCase();
756	        for (Pet pet : getPetsInternal()) {
757	            if (!ignoreNew || !pet.isNew()) {
758	                String compName = pet.getName();
759	                compName = compName.toLowerCase();
760	                if (compName.equals(name)) {
761	                    return pet;
762	                }
763	            }
764	        }
765	        return null;
766	    }
767	
768	    public Pet getPet(Integer petId) {
769	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
770	    }
771	
772	    @Override
773	    public String toString() {
774	        return new ToStringCreator(this)
775	
776	            .append("id", this.getId())
777	            .append("new", this.isNew())
778	            .append("lastName", this.getLastName())
779	            .append("firstName", this.getFirstName())
780	            .append("address", this.address)
781	            .append("city", this.city)
782	            .append("telephone", this.telephone)
783	            .append("email", this.email)
784	            .toString();
785	    }
786	}
